// ── Normalize + validate the raw inbound lead ────────────────────────────────
// Accepts payloads from web forms, chat widgets, ad lead-gen, or another tool.
const out = [];

for (const item of $input.all()) {
  const raw = item.json.body ?? item.json;

  const pick = (...keys) => {
    for (const k of keys) {
      const v = raw[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  const email = pick('email', 'Email', 'email_address', 'work_email').toLowerCase();
  let firstName = pick('firstName', 'first_name', 'fname', 'given_name');
  let lastName = pick('lastName', 'last_name', 'lname', 'family_name');
  const fullName = pick('name', 'fullName', 'full_name');

  if (!firstName && fullName) {
    const parts = fullName.split(/\s+/);
    firstName = parts.shift() || '';
    lastName = lastName || parts.join(' ');
  }

  const phoneRaw = pick('phone', 'phoneNumber', 'phone_number', 'mobile');
  const phone = phoneRaw.replace(/[^\d+]/g, '');

  const emailValid = /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/.test(email);
  const domain = emailValid ? email.split('@')[1] : '';

  const FREE_DOMAINS = [
    'gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com','aol.com',
    'proton.me','protonmail.com','live.com','mail.com','yandex.com','gmx.com',
    'rediffmail.com','zoho.com'
  ];
  const ROLE_PREFIXES = ['info','admin','support','sales','contact','hello','noreply','no-reply','billing','webmaster'];

  const isFreeDomain = FREE_DOMAINS.includes(domain);
  const isRoleAddress = ROLE_PREFIXES.includes(email.split('@')[0]);

  const company = pick('company', 'companyName', 'company_name', 'organization')
    || (domain && !isFreeDomain ? domain.split('.')[0].replace(/[-_]/g, ' ') : '');

  const message = pick('message', 'notes', 'comments', 'enquiry', 'inquiry', 'description', 'how_can_we_help');

  // Honeypot field: real users never fill this in.
  const honeypot = pick('website_url_hp', 'hp', '_honey');

  const lead = {
    receivedAt: new Date().toISOString(),
    email,
    firstName,
    lastName,
    fullName: fullName || [firstName, lastName].filter(Boolean).join(' '),
    phone,
    company,
    jobTitle: pick('jobTitle', 'title', 'job_title', 'role'),
    companySize: pick('companySize', 'company_size', 'employees', 'headcount'),
    budget: pick('budget', 'budget_range'),
    timeline: pick('timeline', 'timeframe', 'when'),
    country: pick('country', 'region'),
    website: pick('website', 'company_website', 'url'),
    message,
    source: pick('source', 'lead_source', 'channel') || 'website_form',
    formName: pick('formName', 'form', 'form_id') || 'unknown',
    pageUrl: pick('pageUrl', 'page_url', 'referrer_page'),
    utm: {
      source: pick('utm_source'),
      medium: pick('utm_medium'),
      campaign: pick('utm_campaign'),
      term: pick('utm_term'),
      content: pick('utm_content'),
    },
    consent: raw.consent === true || String(raw.consent ?? '').toLowerCase() === 'true',
    emailDomain: domain,
    isFreeDomain,
    isRoleAddress,
  };

  const errors = [];
  if (!emailValid) errors.push('invalid_or_missing_email');
  if (!lead.fullName) errors.push('missing_name');
  if (honeypot) errors.push('honeypot_triggered');

  out.push({
    json: {
      ...lead,
      isValid: errors.length === 0,
      validationErrors: errors,
    },
  });
}

return out;

