parameters.jsCode:
// ── Blend the AI judgement with deterministic firmographic rules ─────────────
// The AI handles language/intent; the rules keep scoring stable and auditable.
const items = [];

for (const item of $input.all()) {
  const lead = $('Normalize & Validate').itemMatching(item.pairedItem?.item ?? 0).json;
  const ai = item.json.output ?? item.json;

  const clamp = (n) => Math.max(0, Math.min(100, Number(n) || 0));

  const fitScore = clamp(ai.fit_score);
  const intentScore = clamp(ai.intent_score);
  const spam = Number(ai.spam_probability) || 0;

  // Weighted base: intent matters slightly more than fit for inbound.
  let score = Math.round(fitScore * 0.45 + intentScore * 0.55);

  const adjustments = [];
  const bump = (points, why) => { score += points; adjustments.push(`${points > 0 ? '+' : ''}${points} ${why}`); };

  if (lead.isFreeDomain) bump(-12, 'personal email domain');
  if (lead.isRoleAddress) bump(-6, 'role-based address');
  if (lead.phone) bump(4, 'phone provided');
  if (lead.company) bump(4, 'company provided');
  if ((lead.message || '').length > 180) bump(5, 'detailed enquiry');
  if ((lead.message || '').length < 20) bump(-8, 'thin enquiry');
  if (/enterprise|procurement|rfp|rfq|contract|pilot|poc/i.test(lead.message || '')) bump(6, 'buying-process language');
  if (/student|assignment|internship|job opening|resume|cv|hiring/i.test(lead.message || '')) bump(-25, 'not a buyer');
  if (lead.utm.campaign) bump(3, 'attributed campaign');

  score = clamp(score);

  // ── Tier + routing ────────────────────────────────────────────────────────
  let tier;
  if (spam >= 0.7 || ai.qualification === 'disqualified' || score < 25) tier = 'disqualified';
  else if (score >= 75) tier = 'hot';
  else if (score >= 50) tier = 'warm';
  else tier = 'cold';

  const routing = {
    hot:          { owner: 'ae-team@yourcompany.com',  pipelineStage: 'qualifiedtobuy',       slaHours: 1,    lifecycleStage: 'salesqualifiedlead' },
    warm:         { owner: 'sdr-team@yourcompany.com', pipelineStage: 'appointmentscheduled', slaHours: 24,   lifecycleStage: 'marketingqualifiedlead' },
    cold:         { owner: 'nurture@yourcompany.com',  pipelineStage: 'lead',                 slaHours: 168,  lifecycleStage: 'lead' },
    disqualified: { owner: 'unassigned',               pipelineStage: 'lead',                 slaHours: null, lifecycleStage: 'other' },
  }[tier];

  items.push({
    json: {
      ...lead,
      ai: {
        qualification: ai.qualification,
        intent: ai.intent,
        seniority: ai.seniority,
        companySizeEstimate: ai.company_size_estimate,
        budgetSignal: ai.budget_signal,
        timelineSignal: ai.timeline,
        useCase: ai.use_case,
        fitScore,
        intentScore,
        spamProbability: spam,
        summary: ai.summary,
        reasoning: ai.reasoning,
        nextStep: ai.suggested_next_step,
      },
      leadScore: score,
      scoreAdjustments: adjustments,
      tier,
      ...routing,
      dealName: `${lead.company || lead.fullName || lead.email} — ${ai.use_case || 'Inbound enquiry'}`,
      processedAt: new Date().toISOString(),
    },
  });
}

return items;

